1249	/* -- viewport-driven sticky floating step header (G5) --------------- */
1250	/*
1251	 * A floating banner that pins to the top of the conversation scroll area and
1252	 * shows the title of whichever step's content currently sits at the viewport
1253	 * top. Shared by the running-flow view (#flow-conversation, its own scroller)
1254	 * and the history view (#history-detail inside the scrolling
1255	 * .history-detail-pane). The outer anchor is a zero-height `position: sticky`
1256	 * box so it never consumes layout height or shifts the conversation; its
1257	 * absolutely-positioned inner button paints the banner over the content top.
1258	 * It is mutually exclusive with the in-stream `.history-step-header` separator
1259	 * rows (JS hides it the instant an original header reaches the top), so the
1260	 * label is never shown twice. Status is carried by the explicit text label, not
1261	 * by colour alone.
1262	 */
1263	.conv-sticky-header {
1264	  position: sticky;
1265	  /* Must equal the negative of the scroll container's padding-top
1266	   * (.flow-conversation / .history-detail-pane both use padding-top: 14px).
1267	   * The sticky `top` threshold is measured against the content box (inner edge
1268	   * of padding); offsetting by -padding-top cancels that padding so the anchor
1269	   * pins to the scroll-viewport edge (outer edge of padding) instead, leaving
1270	   * no gap between the floating header and the top of the scroll region. */
1271	  top: -14px;
1272	  height: 0;
1273	  z-index: 6;
1274	  overflow: visible;
1275	  pointer-events: none;
1276	}
1277	.conv-sticky-header.hidden { display: none; }
1278	.conv-sticky-header__inner {
1279	  position: absolute;
1280	  top: 0;
1281	  left: 0;
1282	  right: 0;
1283	  display: flex;
1284	  align-items: center;
1285	  width: 100%;
1286	  margin: 0;
1287	  padding: 7px 11px;
1288	  background: var(--bg-raised);
1289	  border: none;
1290	  border-bottom: 1px solid var(--border);
1291	  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.28);
1292	  font: inherit;
1293	  font-size: 12px;
1294	  text-transform: uppercase;
1295	  letter-spacing: 0.04em;
1296	  color: var(--cyan);
1297	  text-align: left;
1298	  cursor: pointer;
1299	  pointer-events: auto;

