5307	// and are skipped.
5308	function findLivePartialBubble(container, segKey) {
5309	  for (const child of container.children) {
5310	    if (child.__convPartial && child.__convSegmentKey === segKey) return child;
5311	  }
5312	  return null;
5313	}
5314	
5315	// Insert `bubble` into `container` keeping all bubbles ordered globally by
5316	// (__convTs, __convIdx). Existing `.history-step-header` rows are skipped
5317	// during the scan — they are stateless separators that get rebuilt by
5318	// `rebuildStepHeaders` after the new bubble has settled into its slot.
5319	function insertBubbleSorted(container, bubble) {
5320	  let ref = null;
5321	  for (const child of container.children) {
5322	    if (child.__convIdx === undefined) continue;
5323	    if (child.__convTs > bubble.__convTs ||
5324	        (child.__convTs === bubble.__convTs &&
5325	         child.__convIdx > bubble.__convIdx)) {
5326	      ref = child;
5327	      break;
5328	    }
5329	  }
5330	  container.insertBefore(bubble, ref);
5331	}
5332	
5333	// Recompute `.history-step-header` separator rows from the current bubble
5334	// order. Headers are stateless — they get fully removed and re-inserted so
5335	// boundaries move with any new in-between bubbles. Stateful bubbles (folds,
5336	// raw toggles, chips) are NEVER touched.
5337	function rebuildStepHeaders(container) {
5338	  const existing = Array.from(container.children).filter(
5339	    (c) => c.classList && c.classList.contains("history-step-header"),
5340	  );
5341	  for (const h of existing) container.removeChild(h);
5342	
5343	  // A header is inserted at the start of every CONTIGUOUS run of a step key —
5344	  // i.e. whenever the key differs from the immediately-previous bubble. Under
5345	  // strict chronological ordering one step_id can be split by another step's
5346	  // records (e.g. SELF_CHECK(A) → IMPLEMENT(B) → SELF_CHECK(A) on a
5347	  // retry/revision loop). A re-appearing step's records physically sit AFTER
5348	  // the interleaving step, so they MUST get their own boundary header: without
5349	  // one the second A segment would render beneath B's header and sticky
5350	  // navigation would mis-attribute that content to B (its viewport-top step
5351	  // would resolve to IMPLEMENT, not SELF_CHECK). Emitting a header per
5352	  // contiguous run keeps each physical segment correctly attributed to its own
5353	  // step. Adjacent same-key bubbles still collapse into one header (no header
5354	  // mid-run) because `lastKey` only changes at a real boundary.
5355	  let lastKey = null;
5356	  const children = Array.from(container.children);
5357	  for (const child of children) {
5358	    if (child.__convStepKey === undefined) continue;
5359	    const key = child.__convStepKey;
5360	    if (key !== lastKey) {
5361	      const header = el("div", "history-step-header");
5362	      // Use the paradigm step name (DISCOVERY / ANALYZE / …); unknown step
5363	      // types fall back to the record's original label / step key.
5364	      const title = stepHeaderLabel(
5365	        child.__convStepType,
5366	        child.__convStepLabel || child.__convStepKey,
5367	      );
5368	      header.appendChild(el("h5", "history-step-title", title));
5369	      container.insertBefore(header, child);
5370	    }
5371	    lastKey = key;
5372	  }
5373	}
