}
.history-item:hover { border-color: var(--accent); }
.history-item.selected { border-color: var(--accent); background: var(--bg-raised); }

.history-item-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 6px;
}
.history-task {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.history-item-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--fg-dim);
  font-size: 11px;
}

.badge-live {
  background: rgba(76,175,106,.2);
  color: var(--green);
}

/* -- history detail (step records) --------------------------------- */

.history-detail { display: flex; flex-direction: column; gap: 14px; }

.history-step {
  border: 1px solid var(--border);
  border-radius: 7px;
  overflow: hidden;
}
.history-step-title {
  margin: 0;
  padding: 7px 11px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--cyan);
}

/* -- viewport-driven sticky floating step header (G5) --------------- */
/*
 * A floating banner that pins to the top of the conversation scroll area and
 * shows the title of whichever step's content currently sits at the viewport
 * top. Shared by the running-flow view (#flow-conversation, its own scroller)
 * and the history view (#history-detail inside the scrolling
 * .history-detail-pane). The outer anchor is a zero-height `position: sticky`
 * box so it never consumes layout height or shifts the conversation; its
 * absolutely-positioned inner button paints the banner over the content top.
 * It is mutually exclusive with the in-stream `.history-step-header` separator
 * rows (JS hides it the instant an original header reaches the top), so the
 * label is never shown twice. Status is carried by the explicit text label, not
 * by colour alone.
 */
.conv-sticky-header {
  position: sticky;
  /* Must equal the negative of the scroll container's padding-top
   * (.flow-conversation / .history-detail-pane both use padding-top: 14px).
   * The sticky `top` threshold is measured against the content box (inner edge
   * of padding); offsetting by -padding-top cancels that padding so the anchor
   * pins to the scroll-viewport edge (outer edge of padding) instead, leaving
   * no gap between the floating header and the top of the scroll region. */
  top: -14px;
  height: 0;
  z-index: 6;
  overflow: visible;
  pointer-events: none;
}
.conv-sticky-header.hidden { display: none; }
.conv-sticky-header__inner {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  width: 100%;
  margin: 0;
  padding: 7px 11px;
  background: var(--bg-raised);
  border: none;
  border-bottom: 1px solid var(--border);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.28);
  font: inherit;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--cyan);
  text-align: left;
  cursor: pointer;
  pointer-events: auto;

