.conv-record.step-status-failed {
  border-left-color: var(--red);
  background: rgba(224, 86, 75, 0.12);
  color: var(--fg);
}

/* -- per-step-type visual grouping (G4) ------------------------------ */
/*
 * Every conversation bubble already carries a stable `step-type-<type>` DOM
 * class (added by addConversationRecords in app.js, G2). Here we turn that
 * class into a low-saturation, distinguishable per-step grouping style so a
 * step's boundary is obvious and all records of one step_id read as one
 * region. Two coordinated signals per step:
 *   1. the record's 3px LEFT RAIL is recoloured to the step accent (it
 *      overrides the role-based left stripe ONLY inside the conversation —
 *      role identity is still carried by the bubble's own alignment + tint,
 *      lines below — so the rail now encodes the STEP, the bubble the ROLE);
 *   2. a very faint full-width BACKGROUND LANE in the same hue, kept at
 *      ~0.07 alpha so it tints the lane without lowering text contrast and
 *      survives on mobile where the rail itself is dropped.
 *
 * Scoped to `.history-detail`, the conversation container shared by BOTH the
 * running-flow view (`#flow-conversation.flow-conversation.history-detail`)
 * and the history-detail view (`#history-detail.history-detail`), so the two
 * views group identically. The non-flow history LIST (`.history-item` /
 * top-level `.history-record`) lives OUTSIDE `.history-detail`, so its 3px
 * left identity stripe and padding are untouched.
 *
 * The lightweight status / DAG markers (`.step-status-row`,
 * `.group-status-marker`) keep their own status-coloured styling (they carry
 * a step-type class too), so they are explicitly excluded here.
 */
.history-detail .conv-record.step-type-discovery:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-discovery);
  background: rgba(91, 143, 214, 0.07);
}
.history-detail .conv-record.step-type-analyze:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-analyze);
  background: rgba(63, 169, 191, 0.07);
}
.history-detail .conv-record.step-type-plan:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-plan);
  background: rgba(138, 130, 224, 0.08);
}
.history-detail .conv-record.step-type-confirm:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-confirm);
  background: rgba(111, 134, 201, 0.07);
}
.history-detail .conv-record.step-type-implement:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-implement);
  background: rgba(87, 168, 106, 0.07);
}
.history-detail .conv-record.step-type-test:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-test);
  background: rgba(63, 174, 154, 0.07);
}
.history-detail .conv-record.step-type-self_check:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-self_check);
  background: rgba(200, 154, 70, 0.08);
}
.history-detail .conv-record.step-type-verify_spec:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-verify_spec);
  background: rgba(208, 130, 78, 0.08);
}
.history-detail .conv-record.step-type-update_spec:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-update_spec);
  background: rgba(84, 174, 196, 0.07);
}
.history-detail .conv-record.step-type-spec_gate:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-spec_gate);
  background: rgba(194, 161, 63, 0.08);
}
.history-detail .conv-record.step-type-version_analyze:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-version_analyze);
  background: rgba(168, 127, 196, 0.08);
}
.history-detail .conv-record.step-type-commit:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-commit);
  background: rgba(121, 168, 63, 0.07);
}
.history-detail .conv-record.step-type-summarize:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-summarize);
  background: rgba(130, 139, 152, 0.09);
}

/* The step-header separator row is the explicit boundary between two step
 * regions. Give it a little extra breathing room above (never before the very
 * first header) so the colour change between lanes is unmistakable; the title
 * keeps its existing reverse-block look. Scoped to the conversation so the
 * history LIST is untouched. */
.history-detail .history-step-header { margin-top: 4px; }
.history-detail .history-step-header:first-child { margin-top: 0; }

/* -- step report card ----------------------------------------------- */
/*
 * Default-expanded report card mirroring the CLI's per-step Rich Panel.
 * Sits inside the .history-step container directly after the raw
 * step_completed chip. No max-height — long reports scroll with the
 * page, not inside a captive viewport (see the running-flow-console
 * spec: per-block height caps are not allowed).
 */
.step-report {
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 7px;
  background: var(--bg-card);
  margin: 4px 0;
  display: flex;
  flex-direction: column;
}

