4787	// as the underlying jsonl files. A lightweight `.history-step-header` row is
4788	// inserted between two adjacent bubbles whenever they cross a step boundary,
4789	// so the user still sees per-step visual grouping; it is purely a separator
4790	// and never changes the physical order of bubbles. A discovery → user reply
4791	// → discovery sequence renders in jsonl-order rather than re-bucketed into
4792	// independent per-step sections.
4793	//
4794	// Incremental updates: an active flow streams `history_data` appends every
4795	// LLM turn. A full rebuild on each append would recreate every
4796	// `makeFoldable` / `makeRawToggle` / chip in its default collapsed state,
4797	// collapsing a record the reader had just expanded. So when `append` is set,
4798	// only the new tail records are built and inserted into the existing DOM —
4799	// bubbles already on screen (and any folds / chips / raw panels the reader
4800	// opened) are untouched. After each batch, step-header separators are
4801	// rebuilt from the now-correctly-ordered bubble list, which keeps the
4802	// stateful bubbles intact while the stateless headers re-shift to wherever
4803	// the latest insertion changed a step boundary.
4804	//
4805	// Per-container reconciliation state lives on `container.__convState`:
4806	//   { count: number of raw records already rendered }
4807	function renderConversation(container, records, append) {
4808	  const st = container.__convState;
4809	  // Fast incremental path: only when we have a live reconciliation state AND
4810	  // the incoming array is a strict superset of what is already rendered
4811	  // (`records.length >= st.count`). A shorter array means the snapshot was
4812	  // replaced out from under us (full re-fetch, reconnect) — fall through to a
4813	  // clean rebuild instead of silently doing nothing, which would otherwise
4814	  // look like the conversation "froze".
4815	  if (append && st && st.count > 0 && records.length >= st.count) {
4816	    if (records.length > st.count) {
4817	      addConversationRecords(container, st, records, st.count);
4818	    }
4819	    return;
4820	  }
4821	  container.innerHTML = "";
4822	  const fresh = { count: 0 };
4823	  container.__convState = fresh;
4824	  if (!records.length) {
4825	    container.appendChild(
4826	      el("p", "empty", "No conversation records for this session."));
4827	    return;
4828	  }
4829	  addConversationRecords(container, fresh, records, 0);
4830	}
4831	
4832	// Build records `records[startIndex..]` and merge them into `container`,
4833	// keeping the whole conversation strictly ordered by `(__convTs, __convIdx)`.
4834	// Each bubble carries its step key so a single linear sweep can rebuild the
4835	// `.history-step-header` separators after all bubbles for this batch have
4836	// been placed.
4837	//
4838	// `st.count` is advanced here (not by the caller) and ALWAYS reaches
4839	// `records.length`, even if an individual record fails to render: a single
4840	// malformed record must never stall the append cursor, or every subsequent
4841	// delta would re-attempt the same broken slot and the stream would freeze.
4842	// Each record is built behind a try/catch and degrades to a minimal
4843	// placeholder bubble (carrying the same ordering metadata) so the rest of the
4844	// batch — and all future appends — keep flowing.
4845	function addConversationRecords(container, st, records, startIndex) {
4846	  // Map every record to a stable segment key over the FULL ordered array (not
4847	  // by inspecting the DOM): same-segment partials (one turn's run of fragments)
4848	  // share a key and merge into one accumulating bubble, while a later round's
4849	  // partials (separated by an intervening final) get a distinct key and a
4850	  // separate bubble. Computing this purely keeps the incremental (append) and
4851	  // full-rebuild paths identical, and is immune to removeSupersededProgress
4852	  // running only at the end of the loop (a just-closed segment's stale bubble
4853	  // still lingers mid-loop, so a DOM probe would mis-merge the next round).
4854	  const segments = partialSegments(records);
4855	  // Per-record cumulative round usage (G5), grouped by step_id over the FULL
4856	  // ordered array so the cumulative is stable regardless of how the batch was
4857	  // sliced. Attached to each norm below so the interactive assistant renderers
4858	  // can show『本轮 … · 累计 …』without re-walking the records.
4859	  const roundCumulative = accumulateRoundUsageByStep(records);
4860	  for (let i = startIndex; i < records.length; i++) {
4861	    const segKey = segments[i];
4862	
4863	    // Partial fragment: fold it into its segment's live accumulating bubble,
4864	    // creating that bubble on the segment's first fragment. A malformed partial
4865	    // must not stall the stream, so on failure we fall through to the generic
4866	    // per-record path below for the same index.
4867	    if (segKey != null) {
4868	      let handled = false;
4869	      try {
4870	        const norm = normalizeRecord(records[i]);
4871	        const live = findLivePartialBubble(container, segKey);
4872	        if (live) {
4873	          appendPartialFragment(live, norm);
4874	          // Track the LATEST fragment for ordering + supersede: the bubble's
4875	          // (ts, idx) become the newest fragment's, so a later final sorts just
4876	          // after it and `superseded.has(child.__convIdx)` (the latest member
