.conv-record { display: flex; flex-direction: column; }

.conv-bubble {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 11px;
  font-size: 12.5px;
  line-height: 1.5;
  max-width: 88%;
  overflow-wrap: anywhere;
}

.conv-record.role-user .conv-bubble {
  align-self: flex-end;
  background: rgba(76, 141, 255, 0.12);
  border-color: rgba(76, 141, 255, 0.4);
}
.conv-record.role-user .history-record-head { flex-direction: row-reverse; }

.conv-record.role-assistant .conv-bubble {
  align-self: flex-start;
  background: rgba(76, 175, 106, 0.10);
  border-color: rgba(76, 175, 106, 0.38);
}

.conv-record.role-system .conv-bubble,
.conv-record.role-other .conv-bubble {
  align-self: stretch;
  max-width: 100%;
  background: rgba(214, 162, 58, 0.08);
  border-color: rgba(214, 162, 58, 0.3);
}
.conv-record.role-other .conv-bubble {
  background: rgba(106, 107, 112, 0.12);
  border-color: var(--border);
}

.conv-plain {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
  font-size: 12px;
  color: var(--fg);
}
.conv-empty { color: var(--fg-dim); font-style: italic; }

